// tramme launch film · music, 120 bpm, A minor; bars FIRST to LAST - 1 of the film (2 s each)
const FIRST = 0, LAST = 12;
const B = 0.5, BAR = 2;
const T = (bar, beat = 0) => (bar - FIRST) * BAR + beat * B;
const playing = (bar) => bar >= FIRST && bar < LAST;
const hz = (m) => 440 * Math.pow(2, (m - 69) / 12);
const R = kit.random;
const human = (v) => v * (0.9 + 0.2 * R());

// the mix: a glue compressor on the master, the tonal parts ducked by the kick
const out = ctx.createGain(); out.gain.value = 0.85;
const glue = ctx.createDynamicsCompressor();
glue.threshold.value = -15; glue.knee.value = 8; glue.ratio.value = 3; glue.attack.value = 0.006; glue.release.value = 0.15;
out.connect(glue).connect(ctx.destination);
const drums = ctx.createGain(); drums.connect(out);
const pump = ctx.createGain(); pump.connect(out);
function duck(t, depth) { pump.gain.setTargetAtTime(1 - depth, t, 0.004); pump.gain.setTargetAtTime(1, t + 0.05, 0.07); }

const SAT = new Float32Array(2048);
for (let i = 0; i < 2048; i++) { const x = i / 1023.5 - 1; SAT[i] = Math.tanh(x * 2.4) / Math.tanh(2.4); }
const NOISE = kit.noise('white', 2).buffer;
function noise(t, dur) { const s = ctx.createBufferSource(); s.buffer = NOISE; s.start(t, R() * 1.4); s.stop(t + dur); return s; }

// a seeded room and a dotted-eighth echo
const ir = ctx.createBuffer(2, Math.floor(ctx.sampleRate * 2.2), ctx.sampleRate);
for (let c = 0; c < 2; c++) { const d = ir.getChannelData(c); for (let i = 0; i < d.length; i++) d[i] = (R() * 2 - 1) * Math.pow(1 - i / d.length, 2.8); }
const verb = ctx.createConvolver(); verb.buffer = ir;
const verbIn = ctx.createGain(); verbIn.gain.value = 0.2;
const verbHP = ctx.createBiquadFilter(); verbHP.type = 'highpass'; verbHP.frequency.value = 350;
verbIn.connect(verbHP).connect(verb).connect(out);
const echoIn = ctx.createGain(); echoIn.gain.value = 0.28;
const echoLP = ctx.createBiquadFilter(); echoLP.type = 'lowpass'; echoLP.frequency.value = 2600;
const echo = ctx.createDelay(2); echo.delayTime.value = B * 0.75;
const feedback = ctx.createGain(); feedback.gain.value = 0.32;
echoIn.connect(echoLP).connect(echo); echo.connect(feedback).connect(echo); echo.connect(out); echo.connect(verbIn);

// ── drums ──
function kick(t, v = 1) {
