  o.frequency.setValueAtTime(190, t); o.frequency.exponentialRampToValueAtTime(58, t + 0.045); o.frequency.exponentialRampToValueAtTime(42, t + 0.32);
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + 0.003); g.gain.setTargetAtTime(0, t + 0.08, 0.11);
  const sh = ctx.createWaveShaper(); sh.curve = SAT;
  o.connect(g).connect(sh).connect(drums); o.start(t); o.stop(t + 0.9);
  const n = noise(t, 0.03), hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 2500;
  const gn = ctx.createGain(); gn.gain.setValueAtTime(0.22 * v, t); gn.gain.setTargetAtTime(0, t + 0.002, 0.006);
  n.connect(hp).connect(gn).connect(drums);
  duck(t, 0.6 * Math.min(1, v));
}
function clap(t, v = 1) {
  const n = noise(t, 0.5), bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 1500; bp.Q.value = 0.9;
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t);
  for (const d of [0, 0.009, 0.019]) { g.gain.setValueAtTime(v, t + d); g.gain.setTargetAtTime(0, t + d + 0.001, 0.004); }
  g.gain.setValueAtTime(v * 0.85, t + 0.028); g.gain.setTargetAtTime(0, t + 0.03, 0.07);
  n.connect(bp).connect(g); g.connect(drums); g.connect(verbIn);
}
function snare(t, v = 1) {
  const n = noise(t, 0.25), bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 2200; bp.Q.value = 0.7;
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + 0.002); g.gain.setTargetAtTime(0, t + 0.004, 0.04);
  const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.setValueAtTime(240, t); o.frequency.exponentialRampToValueAtTime(170, t + 0.06);
  const go = ctx.createGain(); go.gain.setValueAtTime(0, t); go.gain.linearRampToValueAtTime(v * 0.6, t + 0.002); go.gain.setTargetAtTime(0, t + 0.004, 0.03);
  n.connect(bp).connect(g); o.connect(go); g.connect(drums); go.connect(drums); g.connect(verbIn);
  o.start(t); o.stop(t + 0.3);
}
function hat(t, v = 1, open = false) {
  const n = noise(t, open ? 0.45 : 0.08), hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = open ? 7000 : 8800;
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + 0.001); g.gain.setTargetAtTime(0, t + 0.002, open ? 0.08 : 0.017);
  n.connect(hp).connect(g).connect(drums);
}
function crash(t, v = 1) {
  const n = noise(t, 1.9), hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 4200;
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + 0.003); g.gain.setTargetAtTime(0, t + 0.01, 0.5);
  n.connect(hp).connect(g); g.connect(drums); g.connect(verbIn);
}

// ── tonal parts ──
const CH = {
  Am: { root: 33, pad: [57, 60, 64, 67], stab: [69, 72, 76], arp: [69, 72, 76, 79] },
  F: { root: 29, pad: [57, 60, 64, 65], stab: [65, 69, 72], arp: [65, 69, 72, 77] },
  C: { root: 36, pad: [55, 60, 62, 64], stab: [67, 72, 76], arp: [67, 72, 74, 79] },
  G: { root: 31, pad: [55, 59, 62, 67], stab: [67, 71, 74], arp: [67, 71, 74, 79] },
};
const SONG = ['Am', 'F', 'Am', 'F', 'Am', 'F', 'C', 'G', 'Am', 'F', 'C', 'G', 'Am', 'F', 'C', 'G', 'Am', 'F', 'C', 'G', 'C', 'C', 'C'];

const bassLP = ctx.createBiquadFilter(); bassLP.type = 'lowpass'; bassLP.frequency.value = 1000; bassLP.connect(pump);
function bass(m, t, len, v = 1) {
  const s = ctx.createOscillator(); s.type = 'sine'; s.frequency.value = hz(m);
  const w = ctx.createOscillator(); w.type = 'sawtooth'; w.frequency.value = hz(m);
  const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.Q.value = 3; f.frequency.setValueAtTime(1600, t); f.frequency.setTargetAtTime(240, t, 0.07);
  const gw = ctx.createGain(); gw.gain.value = 0.32;
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v * 0.5, t + 0.005); g.gain.setValueAtTime(v * 0.5, t + len - 0.03); g.gain.linearRampToValueAtTime(0, t + len);
  s.connect(g); w.connect(f).connect(gw).connect(g); g.connect(bassLP);
  s.start(t); w.start(t); s.stop(t + len + 0.05); w.stop(t + len + 0.05);
}

const padLP = ctx.createBiquadFilter(); padLP.type = 'lowpass'; padLP.Q.value = 0.5;
const padOut = ctx.createGain(); padOut.gain.value = 0.5; padLP.connect(padOut); padOut.connect(pump); padOut.connect(verbIn);
function pad(notes, t, len, v = 1) {
  for (const m of notes) for (const det of [-10, 0, 10]) {
    const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = hz(m); o.detune.value = det + (R() - 0.5) * 4;
    const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.045 * v, t + 0.25); g.gain.setValueAtTime(0.045 * v, t + len); g.gain.linearRampToValueAtTime(0, t + len + 0.5);
    o.connect(g).connect(padLP); o.start(t); o.stop(t + len + 0.6);
  }
}
// the pad's filter: closed in the intro, opening into the drop, low in the break, wide open in the drops
const CUTOFF = [350, 1400, 2600, 2600, 2000, 2000, 2200, 2400, 3200, 3200, 3200, 3200, 3200, 1500, 1800, 2400, 3400, 3400, 2400, 2800, 2600, 1800, 900];
padLP.frequency.setValueAtTime(CUTOFF[Math.max(0, FIRST)], 0);
for (let bar = Math.max(0, FIRST); bar < LAST - 1 && bar < CUTOFF.length - 1; bar++) padLP.frequency.setTargetAtTime(CUTOFF[bar + 1], T(bar, 2), 0.5);

const arpLP = ctx.createBiquadFilter(); arpLP.type = 'lowpass'; arpLP.frequency.value = 4200;
const arpOut = ctx.createGain(); arpLP.connect(arpOut); arpOut.connect(pump); arpOut.connect(echoIn);
function pluck(m, t, v) {
  const o = ctx.createOscillator(); o.type = 'square'; o.frequency.value = hz(m);
  const o2 = ctx.createOscillator(); o2.type = 'triangle'; o2.frequency.value = hz(m) * 2;
  const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.Q.value = 4; f.frequency.setValueAtTime(5200, t); f.frequency.setTargetAtTime(700, t, 0.05);
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + 0.003); g.gain.setTargetAtTime(0, t + 0.004, 0.08);
  const g2 = ctx.createGain(); g2.gain.value = 0.3;
  o.connect(f); o2.connect(g2).connect(f); f.connect(g).connect(arpLP);
  o.start(t); o2.start(t); o.stop(t + 0.6); o2.stop(t + 0.6);
}
function stab(notes, t, v = 1, len = 0.3) {
  const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.Q.value = 3; f.frequency.setValueAtTime(7500, t); f.frequency.setTargetAtTime(1000, t + 0.01, 0.09);
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v * 0.13, t + 0.004); g.gain.setTargetAtTime(0, t + 0.02, len / 3);
  f.connect(g); g.connect(out); g.connect(verbIn); g.connect(echoIn);
  for (const m of notes) for (const det of [-12, 12]) { const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = hz(m); o.detune.value = det; o.connect(f); o.start(t); o.stop(t + len * 3); }
}
const leadOut = ctx.createGain(); leadOut.gain.value = 0.5; leadOut.connect(out); leadOut.connect(echoIn); leadOut.connect(verbIn);
function lead(m, t, len, v = 1) {
  const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.Q.value = 2; f.frequency.setValueAtTime(900, t); f.frequency.linearRampToValueAtTime(4600, t + 0.025); f.frequency.setTargetAtTime(1900, t + 0.03, 0.14);
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.2 * v, t + 0.008); g.gain.setValueAtTime(0.2 * v, t + len); g.gain.setTargetAtTime(0, t + len, 0.05);
  f.connect(g).connect(leadOut);
  for (const [type, det, mul, lvl] of [['sawtooth', -8, 1, 1], ['sawtooth', 8, 1, 1], ['square', 0, 0.5, 0.6]]) {
    const o = ctx.createOscillator(); o.type = type; o.frequency.value = hz(m) * mul; o.detune.value = det;
    const gl = ctx.createGain(); gl.gain.value = lvl;
    o.connect(gl).connect(f); o.start(t); o.stop(t + len + 0.4);
  }
}
// the hook: [sixteenth, note, length in sixteenths] for each chord
const HOOK = {
  Am: [[0, 76, 1.5], [2, 76, 1.5], [4, 79, 1.5], [6, 76, 1], [7, 74, 1], [8, 72, 3], [12, 69, 1.5], [14, 72, 1.5]],
  F: [[0, 77, 1.5], [2, 77, 1.5], [4, 81, 1.5], [6, 77, 1], [7, 76, 1], [8, 72, 3], [12, 69, 1.5], [14, 72, 1.5]],
  C: [[0, 79, 1.5], [2, 79, 1.5], [4, 84, 1.5], [6, 79, 1], [7, 76, 1], [8, 76, 3], [12, 72, 1.5], [14, 74, 1.5]],
  G: [[0, 74, 2], [2, 71, 2], [4, 74, 2], [6, 79, 4], [12, 81, 1.5], [14, 83, 1.5]],
};
const ARP = [0, 1, 2, 3, 2, 1, 0, 1, 0, 1, 2, 3, 2, 3, 1, 2];
const BASS = [[0, 0, 1.5], [3, 12, 1], [6, 0, 1.5], [8, 0, 1.5], [10, 12, 1], [11, 0, 1], [14, 10, 1.5]];
const S = 0.125;

// ── the arrangement, bar by bar ──
for (let bar = 0; bar < SONG.length; bar++) {
  if (!playing(bar)) continue;
  const ch = CH[SONG[bar]], t0 = T(bar);
  const drop = (bar >= 8 && bar <= 12) || bar === 16 || bar === 17;
  const groove = bar >= 4 && bar <= 7;
  const dropA = bar === 2 || bar === 3;

  // pad: everywhere but the logo, which has its own long chord
  if (bar < 20) pad(ch.pad, t0, BAR, bar < 2 ? 0.8 : bar >= 13 && bar <= 14 ? 1.5 : 1);

  // intro: the ball's landings (beats 1 to 6) thump softly; hats come in on bar 1
  if (bar === 0) for (const b of [1, 2, 3]) kick(T(bar, b), 0.45);
  if (bar === 1) { for (const b of [0, 1, 2]) kick(T(bar, b), 0.5); for (let b = 0; b < 4; b++) hat(T(bar, b + 0.5), 0.1); }

  // drop A: one stab a word, four on the floor, the "t" hit hard, a fill into the zoom
  if (dropA) {
    for (let b = 0; b < 4; b++) {
      if (!(bar === 3 && b === 3)) kick(T(bar, b), 1);
      hat(T(bar, b + 0.5), 0.22, true);
      bass(ch.root + 12, T(bar, b + 0.5), 0.22, 0.9);
    }
    clap(T(bar, 1), 0.5); clap(T(bar, 3), 0.5);
    const words = bar === 2
      ? [[0, [69, 72, 76]], [1, [72, 76, 79]], [2, [76, 79, 84]], [3, [79, 84, 88]]]
      : [[0, [77, 81, 84]], [1, [65, 69, 72, 77, 81, 84]]];
    for (const [b, notes] of words) stab(notes, T(bar, b), b === 1 && bar === 3 ? 1.5 : 1, b === 1 && bar === 3 ? 0.9 : 0.3);
    if (bar === 3) for (let i = 0; i < 4; i++) snare(T(bar, 3 + i * 0.25), 0.25 + i * 0.12);
    crash(T(bar), bar === 2 ? 0.5 : 0.3);
  }

  // groove and drops: four on the floor, claps on 2 and 4, sixteenth hats, the bass line, the arpeggio
  if (groove || drop || bar === 18 || bar === 19) {
    const last = bar === 19 ? 3 : 4;
    for (let b = 0; b < last; b++) kick(T(bar, b), 1);
    if (bar !== 19) { clap(T(bar, 1), 0.55); clap(T(bar, 3), 0.55); }
    for (let s = 0; s < (bar === 19 ? 12 : 16); s++) hat(T(bar, s / 4), human(s % 4 === 2 ? 0.2 : s % 2 ? 0.07 : 0.11), s % 4 === 2 && drop);
    for (const [s, off, len] of BASS) if (bar !== 19 || s < 12) bass(ch.root + 12 + off, t0 + s * S, len * S, drop ? 1 : 0.85);
    if (bar >= 5) for (let s = 0; s < (bar === 19 ? 12 : 16); s++) pluck(ch.arp[ARP[s]] + (drop ? 12 : 0), t0 + s * S, human(drop ? 0.07 : 0.09) * (s % 4 === 0 ? 1.2 : 1));
    if (drop) for (const [s, m, len] of HOOK[SONG[bar]]) lead(m, t0 + s * S, len * S, bar === 8 || bar === 16 ? 0.9 : 1);
    if (drop && bar % 2 === 0) crash(t0, 0.32);
  }
  // the end of bar 12: everything stops for the break
  if (bar === 12) for (let i = 0; i < 4; i++) snare(T(bar, 3 + i * 0.25), 0.2 + i * 0.1);

  // the break: no drums, then the beat comes back when "Apply" is pressed (bar 14, beat 2)
  // the break keeps a held low note and the arpeggio, so it breathes rather than stops
  if (bar === 13 || bar === 14) bass(ch.root + 12, t0, bar === 13 ? BAR * 0.98 : BAR * 0.5, 0.55);
  if (bar === 13) for (let s = 0; s < 16; s += 2) pluck(ch.arp[ARP[s]], t0 + s * S, 0.1);
  if (bar === 14) {
    for (let s = 0; s < 16; s += 2) pluck(ch.arp[ARP[s]], t0 + s * S, 0.11);
    kick(T(bar, 2), 0.8); kick(T(bar, 3), 0.8); hat(T(bar, 2.5), 0.12); hat(T(bar, 3.5), 0.12);
    bass(ch.root + 12, T(bar, 2), 0.4, 0.8); bass(ch.root + 12, T(bar, 3), 0.4, 0.8);
  }
  // the build: quarter kicks, a snare roll that doubles, a gap before the drop
  if (bar === 15) {
    for (let b = 0; b < 3; b++) kick(T(bar, b), 0.9);
    for (let i = 0; i < 8; i++) snare(T(bar, i * 0.25), 0.12 + i * 0.02);
    for (let i = 0; i < 12; i++) snare(T(bar, 2 + i / 8), 0.3 + i * 0.04);
    for (let s = 0; s < 14; s++) pluck(ch.arp[ARP[s]] + 12, t0 + s * S, 0.05 + s * 0.004);
  }

  // the logo: one long chord on the hit, a held low C, the room ringing out
  if (bar === 20) {
    kick(t0, 1.1);
    bass(36, t0, 3.2, 1);
    pad([48, 55, 60, 62, 64, 67, 71], t0, 3.4, 1.15);
  }
}
// the very end fades out with the film
if (LAST >= 23) { out.gain.setValueAtTime(0.85, T(21, 2)); out.gain.linearRampToValueAtTime(0, T(22, 2.4)); }
